{
  "report": "Resumo executivo (VALE3 — 2024-03-01): No curto/médio prazo a ação mostra recuperação técnica incipiente, mas o viés de fundo ainda é de baixa. Preço de fechamento em 66.88 está levemente acima da MM20/BB_mid (66.60), mas permanece abaixo da MM200 (68.52) e da MM50 (70.15). O momentum técnico vem melhorando (MACD acima da linha de sinal) porém o MACD continua abaixo de zero; o RSI em 45,95 é neutro. Volatilidade pelas Bandas de Bollinger está moderada e sem sinal de rompimento direcional com confirmação por volume.",
  "signal": "Neutro",
  "support_levels": [
    66.6,
    65.51,
    65.1594
  ],
  "resistance_levels": [
    67.2748,
    68.0406,
    68.5181,
    70.1468
  ],
  "indicator_readings": [
    {
      "indicator": "Preço (fechamento)",
      "reading": "66.88",
      "interpretation": "Fechamento ligeiramente acima da MM20 (66.60) — suporte imediato; ainda abaixo de MM50/MM200, indicando viés de médio-longo prazo baixista."
    },
    {
      "indicator": "MM20",
      "reading": "66.6000",
      "interpretation": "Curto prazo: serve como suporte imediato; MM20 está abaixo da MM50 e MM200, o que confirma pressão vendedora estrutural."
    },
    {
      "indicator": "MM50",
      "reading": "70.1468",
      "interpretation": "Médio prazo: preço significativamente abaixo da MM50 — tendência de médio prazo continua negativa até recuperação acima desta média."
    },
    {
      "indicator": "MM200",
      "reading": "68.5181",
      "interpretation": "Longo prazo: preço abaixo do MM200; reversão consistente exigirá retorno acima do MM200 e depois da MM50."
    },
    {
      "indicator": "EMA9",
      "reading": "66.8480",
      "interpretation": "Reage rápido: EMA9 está ligeiramente abaixo da EMA21 e próximo ao preço — leve pressão vendedora de curtíssimo prazo."
    },
    {
      "indicator": "EMA21",
      "reading": "67.2748",
      "interpretation": "Resistência imediata: preço precisa superar 67.27 para ampliar recuperação de curto prazo."
    },
    {
      "indicator": "MACD / Signal / Hist",
      "reading": "MACD -0.7128 | Signal -0.9825 | Hist +0.2698",
      "interpretation": "MACD negativo mas acima da linha de sinal (histograma positivo): momentum de curto prazo em recuperação, porém ainda fraco enquanto MACD < 0."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "Lower 65.1594 | Mid 66.6000 | Upper 68.0406",
      "interpretation": "Preço perto da banda média; largura das bandas moderada (volatilidade controlada). Suporte técnico relevante em BB_lower 65.16; rompimento das bandas daria direção mais clara."
    },
    {
      "indicator": "RSI14",
      "reading": "45.9496",
      "interpretation": "Neutro — sem sobrecompra/sobrevenda. Não há divergência evidente que confirme reversão forte."
    },
    {
      "indicator": "Volume (último pregão)",
      "reading": "149385755800",
      "interpretation": "Volume moderado no fechamento; a recuperação de final de fevereiro não foi consistentemente acompanhada por aumento de volume, diminuindo a convicção do movimento de alta."
    }
  ]
}
